import * as T from './vendor/three.module.js';
import {createPlayerAvatar} from './player-model.js';
export const shopWalls=[{x:-3,z:0,w:.4,d:6},{x:3,z:0,w:.4,d:6},{x:0,z:-3,w:6.4,d:.4},{x:-2,z:3,w:2.4,d:.4},{x:2,z:3,w:2.4,d:.4},{x:0,z:-1.2,w:3.5,d:.8}];
export function shopCollision(origin,x,y,z,r=.32){const lx=x-origin.x,lz=z-origin.z;if(y<origin.y||y>origin.y+5.7)return false;return shopWalls.some(b=>Math.abs(lx-b.x)<b.w/2+r&&Math.abs(lz-b.z)<b.d/2+r)||(Math.abs(lx)<.3+r&&Math.abs(lz+2.1)<.25+r)||(y>origin.y+3.85&&Math.abs(lx)<3.2+r&&Math.abs(lz)<3.2+r);}
export function canTalkToShopkeeper(origin,pos,mounted=false){return !mounted&&Math.abs(pos.x-origin.x)<2.7&&pos.z>origin.z-1.05&&pos.z<origin.z+2.7&&Math.abs(pos.y-origin.y-1.8)<1.5;}
export function createShopBuilding({scene,x,z,y}){const group=new T.Group(),solids=[],geo=new T.BoxGeometry(1,1,1);group.position.set(x,y,z);scene.add(group);function box(px,py,pz,w,h,d,color,solid=true){const mesh=new T.Mesh(geo,new T.MeshLambertMaterial({color}));mesh.position.set(px,py,pz);mesh.scale.set(w,h,d);group.add(mesh);if(solid)solids.push(mesh);return mesh;}
box(0,.075,0,6.4,.15,6.4,0xb99a74);for(const wall of shopWalls)box(wall.x,wall.z===-1.2?.7:2,wall.z,wall.w,wall.z===-1.2?1.4:4,wall.d,wall.z===-1.2?0xb5814b:0xd8bd83);box(0,4.2,0,6.8,.4,6.8,0xb66f51);box(0,3.7,3,1.6,.6,.4,0xd8bd83);
// Shelves and costumes sit behind the counter, outside the visitor walkway.
for(const px of [-1.8,1.8]){box(px,2,-2.7,1.4,.15,.5,0x91653e,false);box(px,1.3,-2.7,1.4,.15,.5,0x91653e,false);box(px,2.35,-2.6,.6,.5,.3,px<0?0x39c9c7:0x9b81c7,false);}
const npc=createPlayerAvatar({color:'#ec9360',top:'safari',bottom:'jeans',hair:'curls',accessory:''}).g;npc.position.set(0,.15,-2.1);npc.rotation.y=Math.PI;group.add(npc);const lamp=new T.PointLight(0xffe2a4,4,9);lamp.position.set(0,3,0);group.add(lamp);
const canvas=document.createElement('canvas');canvas.width=512;canvas.height=96;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff5d4';ctx.fillRect(0,0,512,96);ctx.fillStyle='#244c3c';ctx.font='bold 38px sans-serif';ctx.textAlign='center';ctx.fillText('BOUTIQUE DES AMIS',256,60);const sign=new T.Mesh(new T.PlaneGeometry(4.5,.85),new T.MeshBasicMaterial({map:new T.CanvasTexture(canvas)}));sign.position.set(0,3.4,3.25);group.add(sign);group.updateMatrixWorld(true);
const origin={x,y,z},aimRay=new T.Raycaster();aimRay.far=5;return {group,solids,origin,contains(px,pz){return Math.abs(px-x)<2.8&&Math.abs(pz-z)<3.2;},floor:y+.15,blocks(px,py,pz,r){return shopCollision(origin,px,py,pz,r);},canTalk(pos,riding){return canTalkToShopkeeper(origin,pos,!!riding);},aimedAt(pos,yaw,pitch,obstacles=[],riding=false){if(!canTalkToShopkeeper(origin,pos,!!riding))return false;group.updateMatrixWorld(true);aimRay.set(pos,new T.Vector3(0,0,-1).applyEuler(new T.Euler(pitch,yaw,0,'YXZ')));const hit=aimRay.intersectObjects([...solids,npc,...obstacles],true)[0];let object=hit?.object;while(object){if(object===npc)return true;object=object.parent;}return false;}};}
